  40  }
  41  
  42  
  43  /** 渠道收到的原始附件描述（落在渠道目录，不直接指向任意本机路径）。 */
  44  export interface ChannelAttachment {
  45    /** 附件稳定标识。 */
  46    id: string;
  47    /** 原始或清洗前的展示文件名。 */
  48    name: string;
  49    /** MIME 类型（可用时）。 */
  50    mime?: string;
  51    /** 字节大小（可用时）。 */
  52    size?: number;
  53    /** 渠道侧落盘引用路径（内部物化使用，历史工具不对外暴露本机路径）。 */
  54    sourceRef: string;
  55    /** 渠道下载是否成功。 */
  56    state: 'available' | 'unavailable';
  57    /** 下载失败原因。 */
  58    reason?: string;
  59  }
  60  
  61  
  62  /** 原始引用消息指向。 */
  63  export interface ChannelReplyTo {
  64    /** 标准 messageId（可用时）。 */
  65    messageId?: string;
  66    /** 平台原始消息 ID。 */
  67    nativeId?: string;
  68  }
  69  
  70  
  71  /** 不可变的来源兼容地址。 */
  72  export interface ChannelOrigin {
  73    /** 渠道名（feishu / wechat / http / cli）。 */
  74    channel: string;
  75    /** 深拷贝的原渠道地址对象。 */
  76    address: Record<string, unknown>;
  77  }
  78  
  79  
  80  /** 来源可见域与授权范围。 */
  81  export interface ChannelVisibility {
  82    /** 作用域字符串描述。 */
  83    scope: string;
  84    /** 是否受信任作用域（如私聊或 trusted 群）。 */
  85    trusted: boolean;
  86    /** 显式配置的公共源白名单。 */
  87    publicSourceIds: string[];
  88  }
  89  
  90  
  91  /** 单机器人路由附带信息。 */
  92  export interface BotRoutingHint {
  93    /** 该机器人在这条消息上是否仅监听当背景。 */
  94    listenOnly: boolean;
  95    /** 是否由决策模型判断是否接话。 */
  96    judge?: boolean;
  97  }
  98  
  99  
 100  /** 渠道路由建议。 */
 101  export interface ChannelRouting {
 102    /** 默认是否仅监听当背景。 */
 103    listenOnly: boolean;
 104    /** 默认是否由决策模型判断。 */
 105    judge?: boolean;
 106    /** 服务端校验过的指定会话号：bots 只投给这场会话的机器人、进这场会话（网页“发给哪个会话”、引用别的渠道的消息）。 */
 107    sessionId?: string;
 108    /** 引用别的渠道的消息时，被引那条的原渠道、原机器人、原会话（入口校验过）；只作记录，回话照旧回本条来源。 */
 109    replyOrigin?: { source: string; bot: string; sessionId: string };
 110    /** 一轮一次 channel_reply 都没调时，把最后的话当 final 直接发出去（一对一的渠道：网页、命令行、微信）；不写走修复轮。 */
 111    autoFinal?: boolean;
 112    /** 多机器人场景下每个机器人各自的监听/判断覆盖项。 */
 113    byBot?: Record<string, BotRoutingHint>;
 114  }
 115  
 116  
 117  /** 网页发话时附带的当前查看上下文（供 131 接入 POST /api/message 的 view 后填入）。 */
 118  export interface ChannelView {
 119    /** 网页当前正在查看的渠道名（feishu / wechat / http / cli）。 */
 120    channel: string;
 121    /** 网页当前正在查看的聊天标识；看的是整个渠道时是 ''。 */
 122    chat: string;
 123    /** 给人看的名字（web-api 照 /api/channels 的清单填）：“飞书·群·测试群”“飞书·全部聊天”；前台这一轮的提示里用它。 */
 124    label?: string;
 125  }
 126  
 127  
```

### 解释
- 都是纯类型，按声明顺序拆成八个子块。

