 706  /**
 707   * 按渠道标准协议校验翻页游标、按模式过滤、按 (createdAt, messageId) 升序稳定分页并生成下一页签名游标。
 708   * @param input 分页入参（请求、渠道、账号、聊天与候选摘要项）。
 709   * @returns 标准渠道历史结果。
 710   */
 711  export function paginateChannelHistory(input: PaginateHistoryInput): ChannelHistoryResult {
 712    const snapshot = input.request.sourceSnapshot;
 713    /** 实际查询作用域描述，固定为 channel:accountId:chatId。 */
 714    const scope = `${input.channel}:${input.accountId}:${input.chatId}`;
 715    /** 预期发送者过滤键（非 visible 模式固定为空串）。 */
 716    const expectedSenderId = input.request.senderId ?? '';
 717    let decodedCursor: HistoryCursorPayload | undefined;
 718  
 719    //G 传入翻页游标时严格核验签名及绑定边界。
 720    if (input.request.before !== undefined && input.request.before !== '') {
 721      decodedCursor = decodeHistoryCursor(input.request.before, {
 722        channel: input.channel,
 723        accountId: input.accountId,
 724        chatId: input.chatId,
 725        mode: input.request.mode,
 726        senderId: expectedSenderId,
 727        botName: snapshot.botName,
 728      });
 729      if (decodedCursor === undefined) {
 730        return {
 731          ok: false,
 732          items: [],
 733          nextCursor: null,
 734          scope,
 735          completeness: 'local_only',
 736          error: { code: 'invalid_cursor', message: '历史翻页游标无效或与当前查询范围不匹配' },
 737        };
 738      }
 739    }
 740  
 741    //M 按查询模式筛选候选消息。
 742    let filtered = input.entries;
 743    if (input.request.mode === 'visible') {
 744      filtered = input.entries.filter((entry) => entry.sender.id === expectedSenderId);
 745    }
 746  
 747    //M 按 (createdAt, messageId) 稳定升序排列，再严格切取游标之前最近 limit 条。
 748    const sorted = [...filtered].sort((a, b) => {
 749      if (a.createdAt !== b.createdAt) return a.createdAt - b.createdAt;
 750      if (a.messageId < b.messageId) return -1;
 751      if (a.messageId > b.messageId) return 1;
 752      return 0;
 753    });
 754  
 755    let bounded = sorted;
 756    if (decodedCursor !== undefined) {
 757      const cursorAt = decodedCursor.beforeAt;
 758      const cursorId = decodedCursor.beforeId;
 759      //M 只保留严格早于上一页游标的时间与消息号，翻页不会重复边界记录。
 760      bounded = sorted.filter((entry) => {
 761        if (entry.createdAt < cursorAt) return true;
 762  
 763        return entry.createdAt === cursorAt && entry.messageId < cursorId;
 764      });
 765    }
 766  
 767    const page = bounded.slice(-input.request.limit);
 768    let nextCursor: string | null = null;
 769    const first = page[0];
 770    if (bounded.length > page.length && first !== undefined) {
 771      //M 还有更早的历史项时，以本页最早一条构造并签名下一页翻页游标。
 772      nextCursor = encodeHistoryCursor({
 773        beforeAt: first.createdAt,
 774        beforeId: first.messageId,
 775        channel: input.channel,
 776        accountId: input.accountId,
 777        chatId: input.chatId,
 778        mode: input.request.mode,
 779        senderId: expectedSenderId,
 780        botName: snapshot.botName,
 781      });
 782    }
 783  
 784    return {
 785      ok: true,
 786      items: page,
 787      nextCursor,
 788      scope,
 789      completeness: 'local_only',
 790    };
 791  }
 792  
 793  
```

