699  /**
700   * 拆跨渠道发话的目标串：trim、去掉网页展示的渠道前缀、拆出“前缀:聊天”。
701   * @param raw 调用方给的原始聊天串。
702   * @param labelPrefixes 渠道的展示前缀（如“飞书·群·”“微信·”），命中第一个就去掉。
703   * @returns 拆好的目标串。
704   */
705  export function parseChatTarget(raw: string, labelPrefixes: string[]): ChatTarget {
706    const exact = raw.trim();
707  
708    //M 去掉网页展示名前面带的渠道前缀，剩下的按名字认。
709    let label = exact;
710    const labelPrefix = labelPrefixes.find((one) => exact.startsWith(one));
711    if (labelPrefix !== undefined) {
712      label = exact.slice(labelPrefix.length);
713    }
714  
715    //M “前缀:聊天”写法：冒号不在开头、两边去空白后都不空才算。
716    const plain = { exact, label, prefix: '', chat: '' };
717    const sep = exact.indexOf(':');
718    if (sep <= 0) return plain;
719  
720    const prefix = exact.slice(0, sep).trim();
721    const chat = exact.slice(sep + 1).trim();
722    if (prefix === '' || chat === '') return plain;
723  
724    return { exact, label, prefix, chat };
725  }
726  
727  
